window.skillsUi = (() => {
  const esc=accountEscape, numerals=['I','II','III','IV'];
  const icons={'market-intelligence':'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 12l2-3 2 1 2-3"/>',luck:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>',security:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',influence:'<path d="M4 4h16v12H10l-6 4V4Z"/><path d="M8 8h8m-8 4h5"/>',locked:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>'};
  const icon=id=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.locked}</svg>`;
  const title=id=>({'market-intelligence':t('Market Intelligence','Marktkenntnis'),luck:t('Luck','Glück'),security:t('Store security','Ladensicherheit'),influence:t('Review influence','Bewertungseinfluss')})[id];
  const explanation=id=>({'market-intelligence':t('Shows how far the current bid is below or above market value on individual item listings.','Zeigt bei Einzelangeboten, wie weit das aktuelle Gebot unter oder über dem Marktwert liegt.'),luck:t('Relative bonus to better-tier odds in newly acquired cases and palettes. Existing sealed contents are fixed.','Relativer Bonus auf höhere Seltenheitsstufen in neu erhaltenen Kisten und Paletten. Bereits versiegelte Inhalte bleiben festgelegt.'),security:t('Increases theft fines at all your stores.','Erhöht Diebstahlbußgelder in allen deinen Läden.'),influence:t('Increases the weight of your verified reviews. Requires a purchase; one review per customer.','Erhöht das Gewicht deiner verifizierten Bewertungen. Erfordert einen Kauf; eine Bewertung pro Kunde.')})[id];
  let data=null,busy=false,error='',pending=null,sequence=0;
  function stop(){sequence++;data=null;busy=false;error='';pending=null;}
  async function load(visit){if(!account)return;const owner=account.id,result=await accountApi('skills');if(visit!==accountVisit||owner!==account?.id)return;data=result;}
  function effect(id,rank){return id==='market-intelligence'?t('Market value comparison','Marktwertvergleich'):id==='luck'?`+${[0,3,5,7][rank]}% ${t('luck','Glück')}`:id==='security'?`+${[0,10,20,30][rank]}% ${t('theft fines','Diebstahlbußgeld')}`:[t('Standard review weight','Normales Bewertungsgewicht'),t('Increased review weight','Erhöhtes Bewertungsgewicht'),t('Higher review weight','Höheres Bewertungsgewicht'),t('Highest review weight','Höchstes Bewertungsgewicht')][rank];}
  function activeBranch(skill){
    const rank=data.ranks[skill.id]||0;
    return `<section class="skill-branch skill-${skill.id}" aria-labelledby="skill-title-${skill.id}"><header><span class="skill-emblem">${icon(skill.id)}</span><h2 id="skill-title-${skill.id}" tabindex="-1">${title(skill.id)}</h2>${infoTip(explanation(skill.id),title(skill.id))}<span class="skill-current-effect">${rank?effect(skill.id,rank):t('Not unlocked','Nicht freigeschaltet')}</span></header><ol class="skill-ranks">${skill.ranks.map(node=>{
      const owned=node.rank<=rank,next=node.available&&node.rank===rank+1,affordable=data.available>=node.cost;
      return `<li class="skill-rank ${owned?'is-owned':next?'is-next':!node.available?'is-future':'is-locked'}"><span class="skill-rank-number" aria-hidden="true">${owned?'✓':numerals[node.rank-1]}</span><div class="skill-rank-copy"><strong>${t('Rank','Rang')} ${numerals[node.rank-1]}</strong><span>${node.available?effect(skill.id,node.rank):t('Coming soon','Kommt bald')}</span>${next&&!affordable?`<small>${t('Need','Es fehlen')} ${node.cost-data.available} ${t('more points','weitere Punkte')}</small>`:''}</div>${owned?`<span class="skill-owned-label">${t('Unlocked','Freigeschaltet')}</span>`:next?`<button type="button" class="skill-upgrade" data-skill-id="${skill.id}" data-skill-rank="${node.rank}" ${busy||!affordable?'disabled':''} aria-label="${esc(title(skill.id))}: ${t('unlock rank','Rang freischalten')} ${numerals[node.rank-1]}, ${node.cost} ${t('skill points','Skillpunkte')}"><strong>${node.cost}</strong> ${t(node.cost===1?'point':'points',node.cost===1?'Punkt':'Punkte')} <span aria-hidden="true">+</span></button>`:`<span class="skill-locked-cost">${icon('locked')}<span>${node.cost} ${t(node.cost===1?'point':'points',node.cost===1?'Punkt':'Punkte')}</span></span>`}</li>`;
    }).join('')}</ol></section>`;
  }
  function render(){
    accountContent.innerHTML=`<div class="skill-tree-page"><header class="skill-tree-hero"><div><h1 tabindex="-1">${t('Skills','Skills')}</h1></div><div class="skill-hero-art" aria-hidden="true"><svg viewBox="0 0 240 190" fill="none"><path d="M120 173V98M120 135 48 75m72 60 72-60m-72 30V37M48 75l-20-38m20 38 20-38m124 38-20-38m20 38 20-38" stroke="currentColor" stroke-width="2"/><circle cx="120" cy="151" r="24" fill="#eab665"/><path d="m120 132 5 11 12 2-9 8 2 12-10-6-10 6 2-12-9-8 12-2Z" stroke="#28363b" stroke-width="2"/><g fill="#243b3d" stroke="currentColor" stroke-width="2"><circle cx="48" cy="75" r="17"/><circle cx="120" cy="69" r="17"/><circle cx="192" cy="75" r="17"/><circle cx="28" cy="37" r="8"/><circle cx="68" cy="37" r="8"/><circle cx="120" cy="23" r="8"/><circle cx="172" cy="37" r="8"/><circle cx="212" cy="37" r="8"/></g><g fill="currentColor"><circle cx="48" cy="75" r="5"/><circle cx="120" cy="69" r="5"/><circle cx="192" cy="75" r="5"/></g></svg></div></header>${!account?`<section class="skill-login"><p>${t('Sign in to unlock skills.','Anmelden, um Skills freizuschalten.')}</p><a href="/login" data-page class="primary-button">${t('Log in','Anmelden')} →</a></section>`:!data?`<p>${t('Loading your skills…','Deine Skills werden geladen …')}</p>`:`<section class="skill-point-bank" aria-label="${t('Your skill points','Deine Skillpunkte')}"><div class="skill-available-points"><span>${icon('luck')}</span><div><strong data-skill-points>${data.available}</strong><span>${t('points available','Punkte verfügbar')}</span></div></div><div class="skill-point-explanation"><strong>${t('1 skill point per level','1 Skillpunkt pro Level')}</strong></div><dl><div><dt>${t('Earned','Erhalten')}</dt><dd>${data.earned}</dd></div><div><dt>${t('Spent','Ausgegeben')}</dt><dd>${data.spent}</dd></div><div><dt>${t('Level','Level')}</dt><dd>${data.level}</dd></div></dl></section>${error?`<p class="account-error" role="alert">${esc(error)}</p>`:''}<div class="skill-tree-root" aria-hidden="true"><span>${icon('luck')}</span><div></div></div><div class="skill-active-branches">${data.skills.filter(skill=>skill.available).map(activeBranch).join('')}</div><section class="skill-future-section" aria-labelledby="skill-future-title"><div class="skill-future-heading"><div><h2 id="skill-future-title">${t('Unavailable skills','Nicht verfügbare Skills')}</h2></div><span>${t('Coming soon','Kommt bald')}</span></div><div class="skill-future-branches">${data.skills.filter(skill=>!skill.available).map(skill=>`<article class="skill-future-branch"><span class="skill-future-emblem">${icon('locked')}</span><div><h3>${esc(t(skill.name,skill.nameDe))}</h3></div><span class="skill-ghost-ranks" aria-hidden="true">○ ─ ○ ─ ○</span></article>`).join('')}</div></section>`}</div>`;
  }
  document.addEventListener('click',async event=>{
    const button=event.target.closest('[data-skill-id]');if(!button||currentAccountPage!=='/skills'||busy||!account)return;
    const skillId=button.dataset.skillId,rank=Number(button.dataset.skillRank),owner=account.id,visit=accountVisit,request=++sequence;
    if(!pending||pending.skillId!==skillId||pending.rank!==rank)pending={skillId,rank,requestId:crypto.randomUUID()};
    busy=true;error='';render();
    try{const result=await accountApi('skills/upgrade',pending);if(request!==sequence||visit!==accountVisit||owner!==account?.id)return;
      pending=null;data=result.tree;updateAccount(result.user);showToast(t('Skill unlocked','Skill freigeschaltet'));
    }catch(failure){if(request!==sequence||visit!==accountVisit||owner!==account?.id)return;error=failure.message;
      if(['skill_rank_changed','insufficient_skill_points'].includes(failure.code)){pending=null;try{const [tree,session]=await Promise.all([accountApi('skills'),accountApi('me')]);if(request!==sequence||visit!==accountVisit||owner!==account?.id)return;data=tree;updateAccount(session.user);}catch{}}
    }finally{if(request===sequence&&visit===accountVisit&&owner===account?.id){busy=false;render();(accountContent.querySelector(`[data-skill-id="${skillId}"]`)||accountContent.querySelector(`#skill-title-${skillId}`))?.focus({preventScroll:true});}}
  });
  return {load,render,stop};
})();
